{"security_risk": "LOW", "summary": "List available Unified Planning oneshot planners installed", "command": "python - <<'PY'
from unified_planning.shortcuts import get_environment
from unified_planning.engines import EngineKind

env = get_environment()
engines = env.factory.engines
oneshot = []
for name, e in engines.items():
    try:
        if env.factory.engine(name).supports(EngineKind.ONESHOT_PLANNER):
            oneshot.append(name)
    except Exception:
        pass
print('oneshot planners:', sorted(oneshot))
PY"}

